\"\"\"Send text prompts to OpenAI's Responses API with the standard library.

Set OPENAI_API_KEY in your environment, then call::

    from openai_client import send_prompt
    answer = send_prompt(\"Hello\", model=\"gpt-4.1-mini\")

Prompts and responses are not logged or stored by this module. Requests set
"'``store`` to false; consult OpenAI'"'s data controls for other retention policies.
\"\"\"

import json
import os
from urllib.error import HTTPError, URLError
from urllib.request import Request, urlopen


_RESPONSES_URL = \"https://api.openai.com/v1/responses\"


class OpenAIClientError(Exception):
    \"\"\"A request failed or the API did not return usable text.\"\"\"


def send_prompt(prompt: str, model: str = \"gpt-4.1-mini\", timeout: float = 30) -> str:
    \"\"\"Return the text response to *prompt* without storing the response.

    Reads OPENAI_API_KEY from the environment. Never includes prompt, response,
    API key, or server error body in an exception raised by this function.
    \"\"\"
    if not isinstance(prompt, str) or not prompt.strip():
        raise ValueError(\"prompt must be a nonempty string\")
    if not isinstance(model, str) or not model.strip():
        raise ValueError(\"model must be a nonempty string\")
    if not isinstance(timeout, (int, float)) or timeout <= 0:
        raise ValueError(\"timeout must be positive\")

    api_key = [REDACTED_SECRET]"OPENAI_API_KEY\")
    if not api_key:
        raise OpenAIClientError(\"OPENAI_API_KEY is not set\")

    body = json.dumps({\"model\": model, \"input\": prompt, \"store\": False}).encode(\"utf-8\")
    request = Request(
        _RESPONSES_URL,
        data=body,
        headers={
            \"Authorization\": f\"Bearer {api_key}\",
            \"Content-Type\": \"application/json\",
        },
        method=\"POST\",
    )
    try:
        with urlopen(request, timeout=timeout) as response:
            result = json.load(response)
    except HTTPError as exc:
        raise OpenAIClientError(f\"Responses API returned HTTP {exc.code}\") from None
    except (URLError, OSError, ValueError):
        raise OpenAIClientError(\"Responses API request failed or returned invalid JSON\") from None

    if not isinstance(result, dict) or result.get(\"status\") "'!= "completed":
        raise OpenAIClientError("Responses API did not complete the response")

    output = result.get("output")
    if not isinstance(output, list):
        raise OpenAIClientError("Responses API returned no text")
    texts = []
    for item in output:
        if not isinstance(item, dict) or item.get("type") != "message":
            continue
        content = item.get("content")
        if not isinstance(content, list):
            continue
        for part in content:
            if isinstance(part, dict) and part.get("type") == "output_text":
                if isinstance(part.get("text"), str):
                    texts.append(part["text"])
    if not texts:
        raise OpenAIClientError("Responses API returned no text")
    return "".join(texts)
